/* DEO GRATIAS — Ordinário da Missa (Missale Romanum 1962)
   Latim: Ordo Missæ conforme o Divinum Officium (acentuação tradicional).
   Português: tradução própria para este jogo (registro litúrgico tradicional,
   tratamento “Vós” a Deus). Recomenda-se revisão por pessoa com formação litúrgica. */
(function (DG) {
  'use strict';
  const O = {};
  const T = (key, la, pt) => { O[key] = { la, pt }; };

  // ---------------- Orações ao paramentar-se (Missale: “Cum sacerdos induitur”) ----------------
  T('vestLavat', 'Da, Dómine, virtútem mánibus meis ad abstergéndam omnem máculam; ut sine pollutióne mentis et córporis váleam tibi servíre.', 'Dai, Senhor, virtude às minhas mãos, para que, purificadas de toda mancha, eu Vos possa servir sem impureza da alma e do corpo.');
  T('vestAmictus', 'Impóne, Dómine, cápiti meo gáleam salútis, ad expugnándos diabólicos incúrsus.', 'Ponde, Senhor, sobre a minha cabeça o elmo da salvação, para repelir os assaltos do demônio.');
  T('vestAlba', 'Deálba me, Dómine, et munda cor meum; ut, in Sánguine Agni dealbátus, gáudiis pérfruar sempitérnis.', 'Purificai-me, Senhor, e limpai o meu coração, para que, alvejado no Sangue do Cordeiro, eu goze das alegrias eternas.');
  T('vestCingulum', 'Præcínge me, Dómine, cíngulo puritátis, et exstíngue in lumbis meis humórem libídinis; ut máneat in me virtus continéntiæ et castitátis.', 'Cingi-me, Senhor, com o cíngulo da pureza e extingui em meus rins o ardor da concupiscência, para que permaneça em mim a virtude da continência e da castidade.');
  T('vestManipulus', 'Mérear, Dómine, portáre manípulum fletus et dolóris; ut cum exsultatióne recípiam mercédem labóris.', 'Mereça eu, Senhor, levar o manípulo do pranto e da dor, para receber com alegria a recompensa do trabalho.');
  T('vestStola', 'Redde mihi, Dómine, stolam immortalitátis, quam pérdidi in prævaricatióne primi paréntis: et, quamvis indígnus accédo ad tuum sacrum mystérium, mérear tamen gáudium sempitérnum.', 'Restituí-me, Senhor, a estola da imortalidade, que perdi pela prevaricação do primeiro pai; e, embora indigno me aproxime do vosso sagrado mistério, mereça eu, contudo, o gozo eterno.');
  T('vestCasula', 'Dómine, qui dixísti: Jugum meum suáve est et onus meum leve: fac, ut istud portáre sic váleam, quod cónsequar tuam grátiam. Amen.', 'Senhor, que dissestes: “O meu jugo é suave e o meu fardo é leve”, fazei que eu o possa levar de tal modo que alcance a vossa graça. Amém.');
  T('adjutoriumSacristia', 'Adjutórium nostrum in nómine Dómini.', 'O nosso auxílio está no nome do Senhor.');
  T('adjutoriumSacristiaR', 'Qui fecit cælum et terram.', 'Que fez o céu e a terra.');
  T('prosit', 'Prosit.', 'Que te seja proveitoso.');
  T('prositR', 'Pro ómnibus et síngulis.', 'Por todos e por cada um.');

  // ---------------- Orações ao pé do altar ----------------
  T('inNomine', 'In nómine Patris, + et Fílii, et Spíritus Sancti. Amen.', 'Em nome do Pai, + e do Filho, e do Espírito Santo. Amém.');
  T('introibo', 'Introíbo ad altáre Dei.', 'Subirei ao altar de Deus.');
  T('adDeum', 'Ad Deum, qui lætíficat juventútem meam.', 'A Deus, que alegra a minha juventude.');
  T('ps42_1', 'Júdica me, Deus, et discérne causam meam de gente non sancta: ab hómine iníquo et dolóso érue me.', 'Julgai-me, ó Deus, e separai a minha causa da gente não santa; livrai-me do homem iníquo e enganador.');
  T('ps42_2', 'Quia tu es, Deus, fortitúdo mea: quare me repulísti, et quare tristis incédo, dum afflígit me inimícus?', 'Pois Vós, ó Deus, sois a minha fortaleza; por que me repelistes? E por que ando triste, enquanto o inimigo me aflige?');
  T('ps42_3', 'Emítte lucem tuam et veritátem tuam: ipsa me deduxérunt, et adduxérunt in montem sanctum tuum et in tabernácula tua.', 'Enviai a vossa luz e a vossa verdade; elas me guiaram e me conduziram ao vosso santo monte e aos vossos tabernáculos.');
  T('ps42_4', 'Et introíbo ad altáre Dei: ad Deum, qui lætíficat juventútem meam.', 'E subirei ao altar de Deus, a Deus que alegra a minha juventude.');
  T('ps42_5', 'Confitébor tibi in cíthara, Deus, Deus meus: quare tristis es, ánima mea, et quare contúrbas me?', 'Louvar-Vos-ei na cítara, ó Deus, meu Deus. Por que estás triste, ó minha alma, e por que me perturbas?');
  T('ps42_6', 'Spera in Deo, quóniam adhuc confitébor illi: salutáre vultus mei, et Deus meus.', 'Espera em Deus, porque ainda O louvarei: Ele é a salvação da minha face e o meu Deus.');
  T('gloriaPatri', 'Glória Patri, et Fílio, et Spirítui Sancto.', 'Glória ao Pai, e ao Filho, e ao Espírito Santo.');
  T('sicutErat', 'Sicut erat in princípio, et nunc, et semper: et in sǽcula sæculórum. Amen.', 'Assim como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amém.');
  T('adjutorium', 'Adjutórium nostrum + in nómine Dómini.', 'O nosso auxílio + está no nome do Senhor.');
  T('quiFecit', 'Qui fecit cælum et terram.', 'Que fez o céu e a terra.');
  T('confiteorP', 'Confíteor Deo omnipoténti, beátæ Maríæ semper Vírgini, beáto Michaéli Archángelo, beáto Joánni Baptístæ, sanctis Apóstolis Petro et Paulo, ómnibus Sanctis, et vobis, fratres: quia peccávi nimis cogitatióne, verbo et ópere:', 'Eu pecador me confesso a Deus todo-poderoso, à bem-aventurada sempre Virgem Maria, ao bem-aventurado São Miguel Arcanjo, ao bem-aventurado São João Batista, aos santos Apóstolos Pedro e Paulo, a todos os Santos, e a vós, irmãos, porque pequei muitas vezes por pensamentos, palavras e obras:');
  T('meaCulpa', 'mea culpa, mea culpa, mea máxima culpa.', 'por minha culpa, por minha culpa, por minha máxima culpa.');
  T('confiteorP2', 'Ideo precor beátam Maríam semper Vírginem, beátum Michaélem Archángelum, beátum Joánnem Baptístam, sanctos Apóstolos Petrum et Paulum, omnes Sanctos, et vos, fratres, oráre pro me ad Dóminum, Deum nostrum.', 'Portanto, rogo à bem-aventurada sempre Virgem Maria, ao bem-aventurado São Miguel Arcanjo, ao bem-aventurado São João Batista, aos santos Apóstolos Pedro e Paulo, a todos os Santos, e a vós, irmãos, que rogueis por mim a Deus, Nosso Senhor.');
  T('misereaturTui', 'Misereátur tui omnípotens Deus, et, dimíssis peccátis tuis, perdúcat te ad vitam ætérnam.', 'Deus todo-poderoso tenha misericórdia de ti, perdoe os teus pecados e te conduza à vida eterna.');
  T('amen', 'Amen.', 'Amém.');
  T('confiteorM', 'Confíteor Deo omnipoténti, beátæ Maríæ semper Vírgini, beáto Michaéli Archángelo, beáto Joánni Baptístæ, sanctis Apóstolis Petro et Paulo, ómnibus Sanctis, et tibi, pater: quia peccávi nimis cogitatióne, verbo et ópere:', 'Eu pecador me confesso a Deus todo-poderoso, à bem-aventurada sempre Virgem Maria, ao bem-aventurado São Miguel Arcanjo, ao bem-aventurado São João Batista, aos santos Apóstolos Pedro e Paulo, a todos os Santos, e a ti, padre, porque pequei muitas vezes por pensamentos, palavras e obras:');
  T('confiteorM2', 'Ideo precor beátam Maríam semper Vírginem, beátum Michaélem Archángelum, beátum Joánnem Baptístam, sanctos Apóstolos Petrum et Paulum, omnes Sanctos, et te, pater, oráre pro me ad Dóminum, Deum nostrum.', 'Portanto, rogo à bem-aventurada sempre Virgem Maria, ao bem-aventurado São Miguel Arcanjo, ao bem-aventurado São João Batista, aos santos Apóstolos Pedro e Paulo, a todos os Santos, e a ti, padre, que rogues por mim a Deus, Nosso Senhor.');
  T('misereaturVestri', 'Misereátur vestri omnípotens Deus, et, dimíssis peccátis vestris, perdúcat vos ad vitam ætérnam.', 'Deus todo-poderoso tenha misericórdia de vós, perdoe os vossos pecados e vos conduza à vida eterna.');
  T('indulgentiam', 'Indulgéntiam, + absolutiónem et remissiónem peccatórum nostrórum tríbuat nobis omnípotens et miséricors Dóminus.', 'O Senhor todo-poderoso e misericordioso nos conceda o perdão, + a absolvição e a remissão dos nossos pecados.');
  T('deusTuConversus', 'Deus, tu convérsus vivificábis nos.', 'Ó Deus, voltando-Vos para nós, dar-nos-eis a vida.');
  T('etPlebsTua', 'Et plebs tua lætábitur in te.', 'E o vosso povo se alegrará em Vós.');
  T('ostendeNobis', 'Osténde nobis, Dómine, misericórdiam tuam.', 'Mostrai-nos, Senhor, a vossa misericórdia.');
  T('etSalutare', 'Et salutáre tuum da nobis.', 'E dai-nos a vossa salvação.');
  T('domineExaudi', 'Dómine, exáudi oratiónem meam.', 'Senhor, ouvi a minha oração.');
  T('etClamor', 'Et clamor meus ad te véniat.', 'E chegue até Vós o meu clamor.');
  T('dominusVobiscum', 'Dóminus vobíscum.', 'O Senhor esteja convosco.');
  T('etCumSpiritu', 'Et cum spíritu tuo.', 'E com o teu espírito.');
  T('oremus', 'Orémus.', 'Oremos.');
  T('aufer', 'Aufer a nobis, quǽsumus, Dómine, iniquitátes nostras: ut ad Sancta sanctórum puris mereámur méntibus introíre. Per Christum, Dóminum nostrum. Amen.', 'Tirai de nós, Senhor, Vos pedimos, as nossas iniquidades, para que mereçamos entrar com almas puras no Santo dos Santos. Por Cristo, Nosso Senhor. Amém.');
  T('oramusTe1', 'Orámus te, Dómine, per mérita Sanctórum tuórum,', 'Nós Vos rogamos, Senhor, pelos méritos dos vossos Santos,');
  T('oramusTe2', 'quorum relíquiæ hic sunt, et ómnium Sanctórum: ut indulgére dignéris ómnia peccáta mea. Amen.', 'cujas relíquias aqui estão, e de todos os Santos, que Vos digneis perdoar-me todos os meus pecados. Amém.');

  // ---------------- Kyrie e Glória ----------------
  T('kyrie', 'Kýrie, eléison.', 'Senhor, tende piedade.');
  T('christe', 'Christe, eléison.', 'Cristo, tende piedade.');
  O.gloria = [
    { la: 'Glória in excélsis', pt: 'Glória', g: 'extJungBow' },
    { la: 'Deo.', pt: 'a Deus nas alturas.', g: 'inclinCapitis' },
    { la: 'Et in terra pax homínibus bonæ voluntátis. Laudámus te. Benedícimus te.', pt: 'E paz na terra aos homens de boa vontade. Nós Vos louvamos. Nós Vos bendizemos.' },
    { la: 'Adorámus te.', pt: 'Nós Vos adoramos.', g: 'inclinCapitis' },
    { la: 'Glorificámus te.', pt: 'Nós Vos glorificamos.' },
    { la: 'Grátias ágimus tibi', pt: 'Nós Vos damos graças', g: 'inclinCapitis' },
    { la: 'propter magnam glóriam tuam. Dómine Deus, Rex cæléstis, Deus Pater omnípotens. Dómine Fili unigénite,', pt: 'pela vossa imensa glória. Senhor Deus, Rei dos céus, Deus Pai todo-poderoso. Senhor Filho unigênito,' },
    { la: 'Jesu Christe.', pt: 'Jesus Cristo.', g: 'inclinCapitis' },
    { la: 'Dómine Deus, Agnus Dei, Fílius Patris. Qui tollis peccáta mundi, miserére nobis. Qui tollis peccáta mundi,', pt: 'Senhor Deus, Cordeiro de Deus, Filho do Pai. Vós que tirais os pecados do mundo, tende piedade de nós. Vós que tirais os pecados do mundo,' },
    { la: 'súscipe deprecatiónem nostram.', pt: 'acolhei a nossa súplica.', g: 'inclinCapitis' },
    { la: 'Qui sedes ad déxteram Patris, miserére nobis. Quóniam tu solus Sanctus. Tu solus Dóminus. Tu solus Altíssimus,', pt: 'Vós que estais sentado à direita do Pai, tende piedade de nós. Porque só Vós sois o Santo. Só Vós, o Senhor. Só Vós, o Altíssimo,' },
    { la: 'Jesu Christe.', pt: 'Jesus Cristo.', g: 'inclinCapitis' },
    { la: 'Cum Sancto Spíritu', pt: 'Com o Espírito Santo,', g: 'signum' },
    { la: 'in glória Dei Patris. Amen.', pt: 'na glória de Deus Pai. Amém.' },
  ];

  // ---------------- Leituras ----------------
  T('deoGratias', 'Deo grátias.', 'Graças a Deus.');
  T('mundaCor', 'Munda cor meum ac lábia mea, omnípotens Deus, qui lábia Isaíæ Prophétæ cálculo mundásti igníto: ita me tua grata miseratióne dignáre mundáre, ut sanctum Evangélium tuum digne váleam nuntiáre. Per Christum, Dóminum nostrum. Amen.', 'Purificai o meu coração e os meus lábios, ó Deus todo-poderoso, que purificastes os lábios do profeta Isaías com uma brasa ardente; dignai-Vos, por vossa benigna misericórdia, purificar-me de tal modo que eu possa anunciar dignamente o vosso santo Evangelho. Por Cristo, Nosso Senhor. Amém.');
  T('jubeDomine', 'Jube, Dómine, benedícere. Dóminus sit in corde meo et in lábiis meis: ut digne et competénter annúntiem Evangélium suum. Amen.', 'Dignai-Vos, Senhor, abençoar-me. O Senhor esteja no meu coração e nos meus lábios, para que eu anuncie digna e competentemente o seu Evangelho. Amém.');
  T('gloriaTibi', 'Glória tibi, Dómine.', 'Glória a Vós, Senhor.');
  T('lausTibi', 'Laus tibi, Christe.', 'Louvor a Vós, ó Cristo.');
  T('perEvangelica', 'Per evangélica dicta deleántur nostra delícta.', 'Pelas palavras do Evangelho sejam apagados os nossos delitos.');

  O.credo = [
    { la: 'Credo in unum', pt: 'Creio em um só', g: 'extJung' },
    { la: 'Deum,', pt: 'Deus,', g: 'inclinCapitis' },
    { la: 'Patrem omnipoténtem, factórem cæli et terræ, visibílium ómnium et invisibílium. Et in unum Dóminum', pt: 'Pai todo-poderoso, criador do céu e da terra, de todas as coisas visíveis e invisíveis. E em um só Senhor,' },
    { la: 'Jesum Christum,', pt: 'Jesus Cristo,', g: 'inclinCapitis' },
    { la: 'Fílium Dei unigénitum. Et ex Patre natum ante ómnia sǽcula. Deum de Deo, lumen de lúmine, Deum verum de Deo vero. Génitum, non factum, consubstantiálem Patri: per quem ómnia facta sunt. Qui propter nos hómines et propter nostram salútem descéndit de cælis.', pt: 'Filho unigênito de Deus. Nascido do Pai antes de todos os séculos. Deus de Deus, Luz da Luz, Deus verdadeiro de Deus verdadeiro. Gerado, não criado, consubstancial ao Pai; por Ele todas as coisas foram feitas. O qual, por nós homens e para a nossa salvação, desceu dos céus.' },
    { la: 'Et incarnátus est de Spíritu Sancto ex María Vírgine: Et homo factus est.', pt: 'E encarnou-Se por obra do Espírito Santo, da Virgem Maria; e Se fez homem.', g: 'genuflectere', hold: true },
    { la: 'Crucifíxus étiam pro nobis: sub Póntio Piláto passus, et sepúltus est. Et resurréxit tértia die, secúndum Scriptúras. Et ascéndit in cælum: sedet ad déxteram Patris. Et íterum ventúrus est cum glória judicáre vivos et mórtuos: cujus regni non erit finis. Et in Spíritum Sanctum, Dóminum et vivificántem: qui ex Patre Filióque procédit. Qui cum Patre et Fílio', pt: 'Também por nós foi crucificado sob Pôncio Pilatos; padeceu e foi sepultado. E ressuscitou ao terceiro dia, conforme as Escrituras. E subiu ao céu, e está sentado à direita do Pai. E de novo há de vir em sua glória, para julgar os vivos e os mortos; e o seu reino não terá fim. E no Espírito Santo, Senhor e fonte de vida, que procede do Pai e do Filho. Que com o Pai e o Filho' },
    { la: 'simul adorátur', pt: 'é juntamente adorado', g: 'inclinCapitis' },
    { la: 'et conglorificátur: qui locútus est per Prophétas. Et unam sanctam cathólicam et apostólicam Ecclésiam. Confíteor unum baptísma in remissiónem peccatórum. Et exspécto resurrectiónem mortuórum.', pt: 'e glorificado; que falou pelos profetas. E na Igreja una, santa, católica e apostólica. Confesso um só batismo para a remissão dos pecados. E espero a ressurreição dos mortos.' },
    { la: 'Et vitam ventúri sǽculi. Amen.', pt: 'E a vida do século futuro. Amém.', g: 'signum' },
  ];

  // ---------------- Ofertório ----------------
  T('suscipeSanctePater', 'Súscipe, sancte Pater, omnípotens ætérne Deus, hanc immaculátam hóstiam, quam ego indígnus fámulus tuus óffero tibi Deo meo vivo et vero, pro innumerabílibus peccátis, et offensiónibus, et neglegéntiis meis, et pro ómnibus circumstántibus, sed et pro ómnibus fidélibus christiánis vivis atque defúnctis: ut mihi, et illis profíciat ad salútem in vitam ætérnam. Amen.', 'Recebei, ó Pai santo, Deus eterno e todo-poderoso, esta hóstia imaculada, que eu, vosso indigno servo, Vos ofereço a Vós, meu Deus vivo e verdadeiro, pelos meus inumeráveis pecados, ofensas e negligências, por todos os circunstantes e também por todos os fiéis cristãos, vivos e defuntos, para que a mim e a eles aproveite para a salvação na vida eterna. Amém.');
  T('deusQuiHumanae1', 'Deus, + qui humánæ substántiæ dignitátem mirabíliter condidísti, et mirabílius reformásti:', 'Ó Deus, + que maravilhosamente criastes a dignidade da natureza humana e mais maravilhosamente ainda a restaurastes,');
  T('deusQuiHumanae2', 'da nobis per hujus aquæ et vini mystérium, ejus divinitátis esse consórtes, qui humanitátis nostræ fíeri dignátus est párticeps, Jesus Christus, Fílius tuus, Dóminus noster: Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus: per ómnia sǽcula sæculórum. Amen.', 'concedei-nos, pelo mistério desta água e deste vinho, sermos participantes da divindade d’Aquele que Se dignou fazer-Se participante da nossa humanidade, Jesus Cristo, vosso Filho, Nosso Senhor, que convosco vive e reina na unidade do Espírito Santo, Deus, por todos os séculos dos séculos. Amém.');
  T('offerimus', 'Offérimus tibi, Dómine, cálicem salutáris, tuam deprecántes cleméntiam: ut in conspéctu divínæ majestátis tuæ, pro nostra et totíus mundi salúte, cum odóre suavitátis ascéndat. Amen.', 'Nós Vos oferecemos, Senhor, o cálice da salvação, implorando a vossa clemência, para que suba com odor de suavidade à presença da vossa divina majestade, pela nossa salvação e de todo o mundo. Amém.');
  T('inSpiritu', 'In spíritu humilitátis et in ánimo contríto suscipiámur a te, Dómine: et sic fiat sacrifícium nostrum in conspéctu tuo hódie, ut pláceat tibi, Dómine Deus.', 'Em espírito de humildade e com o coração contrito sejamos por Vós recebidos, Senhor; e assim se faça hoje o nosso sacrifício em vossa presença, que Vos seja agradável, Senhor Deus.');
  T('veniSanctificator1', 'Veni, sanctificátor omnípotens ætérne Deus:', 'Vinde, ó Santificador, Deus eterno e todo-poderoso,');
  T('veniSanctificator2', 'et béne + dic hoc sacrifícium, tuo sancto nómini præparátum.', 'e abençoai + este sacrifício, preparado para a glória do vosso santo nome.');
  T('lavabo', 'Lavábo inter innocéntes manus meas: et circúmdabo altáre tuum, Dómine: Ut áudiam vocem laudis, et enárrem univérsa mirabília tua. Dómine, diléxi decórem domus tuæ et locum habitatiónis glóriæ tuæ. Ne perdas cum ímpiis, Deus, ánimam meam, et cum viris sánguinum vitam meam: In quorum mánibus iniquitátes sunt: déxtera eórum repléta est munéribus. Ego autem in innocéntia mea ingréssus sum: rédime me et miserére mei. Pes meus stetit in dirécto: in ecclésiis benedícam te, Dómine.', 'Lavarei as minhas mãos entre os inocentes e andarei em torno do vosso altar, Senhor, para ouvir a voz do louvor e narrar todas as vossas maravilhas. Senhor, amei a beleza da vossa casa e o lugar onde habita a vossa glória. Não percais, ó Deus, a minha alma com os ímpios, nem a minha vida com os homens sanguinários, em cujas mãos há iniquidades e cuja direita está cheia de presentes. Eu, porém, caminhei na minha inocência; resgatai-me e tende piedade de mim. O meu pé está firme no caminho reto; nas assembleias Vos bendirei, Senhor.');
  T('gloriaPatriFull', 'Glória Patri, et Fílio, et Spirítui Sancto. Sicut erat in princípio, et nunc, et semper: et in sǽcula sæculórum. Amen.', 'Glória ao Pai, e ao Filho, e ao Espírito Santo. Assim como era no princípio, agora e sempre, e por todos os séculos dos séculos. Amém.');
  T('suscipeSanctaTrinitas', 'Súscipe, sancta Trínitas, hanc oblatiónem, quam tibi offérimus ob memóriam passiónis, resurrectiónis, et ascensiónis Jesu Christi, Dómini nostri: et in honórem beátæ Maríæ semper Vírginis, et beáti Joánnis Baptístæ, et sanctórum Apostolórum Petri et Pauli, et istórum et ómnium Sanctórum: ut illis profíciat ad honórem, nobis autem ad salútem: et illi pro nobis intercédere dignéntur in cælis, quorum memóriam ágimus in terris. Per eúndem Christum, Dóminum nostrum. Amen.', 'Recebei, ó Santíssima Trindade, esta oblação que Vos oferecemos em memória da Paixão, Ressurreição e Ascensão de Jesus Cristo, Nosso Senhor, e em honra da bem-aventurada sempre Virgem Maria, de São João Batista, dos santos Apóstolos Pedro e Paulo, destes e de todos os Santos; para que a eles aproveite para honra e a nós para salvação; e eles se dignem interceder por nós no céu, enquanto fazemos memória deles na terra. Pelo mesmo Cristo, Nosso Senhor. Amém.');
  T('orateFratres', 'Oráte, fratres: ut meum ac vestrum sacrifícium acceptábile fiat apud Deum Patrem omnipoténtem.', 'Orai, irmãos, para que o meu e vosso sacrifício seja aceito por Deus Pai todo-poderoso.');
  T('suscipiat', 'Suscípiat Dóminus sacrifícium de mánibus tuis ad laudem et glóriam nóminis sui, ad utilitátem quoque nostram, totiúsque Ecclésiæ suæ sanctæ.', 'Receba o Senhor de tuas mãos este sacrifício, para louvor e glória do seu nome, para nosso proveito e de toda a sua santa Igreja.');

  // ---------------- Prefácio e Sanctus ----------------
  T('perOmnia', 'Per ómnia sǽcula sæculórum.', 'Por todos os séculos dos séculos.');
  T('sursumCorda', 'Sursum corda.', 'Corações ao alto.');
  T('habemus', 'Habémus ad Dóminum.', 'Já os temos elevados ao Senhor.');
  T('gratiasAgamus', 'Grátias agámus Dómino, Deo nostro.', 'Demos graças ao Senhor, nosso Deus.');
  T('dignum', 'Dignum et justum est.', 'É digno e justo.');
  T('sanctus1', 'Sanctus, Sanctus, Sanctus Dóminus, Deus Sábaoth. Pleni sunt cæli et terra glória tua. Hosánna in excélsis.', 'Santo, Santo, Santo é o Senhor, Deus dos exércitos. Os céus e a terra estão cheios da vossa glória. Hosana nas alturas.');
  T('benedictus', 'Benedíctus, qui venit in nómine Dómini. Hosánna in excélsis.', 'Bendito o que vem em nome do Senhor. Hosana nas alturas.');

  // ---------------- Cânon Romano ----------------
  T('teIgitur1', 'Te ígitur, clementíssime Pater, per Jesum Christum, Fílium tuum, Dóminum nostrum, súpplices rogámus, ac pétimus,', 'A Vós, pois, Pai clementíssimo, por Jesus Cristo, vosso Filho, Nosso Senhor, suplicantes rogamos e pedimos');
  T('teIgitur2', 'uti accépta hábeas et benedícas,', 'que aceiteis e abençoeis');
  T('teIgitur3', 'hæc + dona, hæc + múnera, hæc + sancta sacrifícia illibáta,', 'estes + dons, estas + dádivas, estes + santos sacrifícios imaculados,');
  T('teIgitur4', 'in primis, quæ tibi offérimus pro Ecclésia tua sancta cathólica: quam pacificáre, custodíre, adunáre et régere dignéris toto orbe terrárum: una cum fámulo tuo Papa nostro N. et Antístite nostro N. et ómnibus orthodóxis, atque cathólicæ et apostólicæ fídei cultóribus.', 'que, em primeiro lugar, Vos oferecemos pela vossa santa Igreja católica: dignai-Vos pacificá-la, guardá-la, uni-la e governá-la por toda a terra, juntamente com o vosso servo, o nosso Papa N., o nosso Bispo N., e todos os ortodoxos e cultores da fé católica e apostólica.');
  T('memento1', 'Meménto, Dómine, famulórum famularúmque tuárum N. et N.', 'Lembrai-Vos, Senhor, dos vossos servos e servas N. e N.');
  T('memento2', 'et ómnium circumstántium, quorum tibi fides cógnita est et nota devótio, pro quibus tibi offérimus: vel qui tibi ófferunt hoc sacrifícium laudis, pro se suísque ómnibus: pro redemptióne animárum suárum, pro spe salútis et incolumitátis suæ: tibíque reddunt vota sua ætérno Deo, vivo et vero.', 'e de todos os aqui presentes, cuja fé e devoção Vos são conhecidas, pelos quais Vos oferecemos, ou que Vos oferecem este sacrifício de louvor, por si e por todos os seus, pela redenção de suas almas, pela esperança de sua salvação e incolumidade, e Vos rendem os seus votos, a Vós, Deus eterno, vivo e verdadeiro.');
  T('communicantesFinis', 'et beatórum Apostolórum ac Mártyrum tuórum, Petri et Pauli, Andréæ, Jacóbi, Joánnis, Thomæ, Jacóbi, Philíppi, Bartholomǽi, Matthǽi, Simónis et Thaddǽi: Lini, Cleti, Cleméntis, Xysti, Cornélii, Cypriáni, Lauréntii, Chrysógoni, Joánnis et Pauli, Cosmæ et Damiáni: et ómnium Sanctórum tuórum; quorum méritis precibúsque concédas, ut in ómnibus protectiónis tuæ muniámur auxílio. Per eúndem Christum, Dóminum nostrum. Amen.', 'e dos vossos bem-aventurados Apóstolos e Mártires Pedro e Paulo, André, Tiago, João, Tomé, Tiago, Filipe, Bartolomeu, Mateus, Simão e Tadeu; Lino, Cleto, Clemente, Xisto, Cornélio, Cipriano, Lourenço, Crisógono, João e Paulo, Cosme e Damião, e de todos os vossos Santos: por seus méritos e preces concedei-nos que em tudo sejamos fortalecidos com o auxílio da vossa proteção. Pelo mesmo Cristo, Nosso Senhor. Amém.');
  O.communicantes = {
    common: { la: 'Communicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,', pt: 'Em comunhão com toda a Igreja, veneramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de nosso Deus e Senhor Jesus Cristo; e também do bem-aventurado José, Esposo da mesma Virgem,' },
    Nat: { la: 'Communicántes, et diem sacratíssimum celebrántes, quo beátæ Maríæ intemeráta virgínitas huic mundo édidit Salvatórem: sed et memóriam venerántes, in primis ejúsdem gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,', pt: 'Em comunhão com toda a Igreja, celebrando o dia sacratíssimo em que a virgindade intacta da bem-aventurada Maria deu a este mundo o Salvador, veneramos também a memória, em primeiro lugar, da mesma gloriosa sempre Virgem Maria, Mãe do mesmo nosso Deus e Senhor Jesus Cristo; e também do bem-aventurado José, Esposo da mesma Virgem,' },
    Epi: { la: 'Communicántes, et diem sacratíssimum celebrántes, quo Unigénitus tuus, in tua tecum glória coætérnus, in veritáte carnis nostræ visibíliter corporális appáruit: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,', pt: 'Em comunhão com toda a Igreja, celebrando o dia sacratíssimo em que o vosso Unigênito, coeterno convosco na vossa glória, apareceu visivelmente em corpo na verdade da nossa carne, veneramos também a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe do mesmo nosso Deus e Senhor Jesus Cristo; e também do bem-aventurado José, Esposo da mesma Virgem,' },
    Pasc: { la: 'Communicántes, et diem sacratíssimum celebrántes Resurrectiónis Dómini nostri Jesu Christi secúndum carnem: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,', pt: 'Em comunhão com toda a Igreja, celebrando o dia sacratíssimo da Ressurreição de Nosso Senhor Jesus Cristo segundo a carne, veneramos também a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe do mesmo nosso Deus e Senhor Jesus Cristo; e também do bem-aventurado José, Esposo da mesma Virgem,' },
    Asc: { la: 'Communicántes, et diem sacratíssimum celebrántes, quo Dóminus noster, unigénitus Fílius tuus, unítam sibi fragilitátis nostræ substántiam in glóriæ tuæ déxtera collocávit: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,', pt: 'Em comunhão com toda a Igreja, celebrando o dia sacratíssimo em que Nosso Senhor, vosso Filho unigênito, colocou à direita da vossa glória a substância da nossa fragilidade, unida a Si, veneramos também a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe do mesmo nosso Deus e Senhor Jesus Cristo; e também do bem-aventurado José, Esposo da mesma Virgem,' },
    Pent: { la: 'Communicántes, et diem sacratíssimum Pentecóstes celebrántes, quo Spíritus Sanctus Apóstolis innúmeris linguis appáruit: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi,', pt: 'Em comunhão com toda a Igreja, celebrando o dia sacratíssimo de Pentecostes, em que o Espírito Santo apareceu aos Apóstolos em inumeráveis línguas, veneramos também a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de nosso Deus e Senhor Jesus Cristo; e também do bem-aventurado José, Esposo da mesma Virgem,' },
  };
  T('hancIgitur1', 'Hanc ígitur oblatiónem servitútis nostræ, sed et cunctæ famíliæ tuæ,', 'Esta oblação, pois, da nossa servidão e também de toda a vossa família,');
  T('hancIgiturPasc', 'quam tibi offérimus pro his quoque, quos regeneráre dignátus es ex aqua et Spíritu Sancto, tríbuens eis remissiónem ómnium peccatórum,', 'que Vos oferecemos também por estes que Vos dignastes regenerar pela água e pelo Espírito Santo, concedendo-lhes a remissão de todos os pecados,');
  T('hancIgitur2', 'quǽsumus, Dómine, ut placátus accípias: diésque nostros in tua pace dispónas, atque ab ætérna damnatióne nos éripi, et in electórum tuórum júbeas grege numerári. Per Christum, Dóminum nostrum. Amen.', 'Vos pedimos, Senhor, que a aceiteis aplacado; disponde os nossos dias na vossa paz, mandai que sejamos livres da condenação eterna e contados no rebanho dos vossos eleitos. Por Cristo, Nosso Senhor. Amém.');
  T('quamOblationem1', 'Quam oblatiónem tu, Deus, in ómnibus, quǽsumus,', 'A qual oblação, Vos pedimos, ó Deus, que Vos digneis tornar em tudo');
  T('quamOblationem2', 'bene + díctam, adscríp + tam, ra + tam, rationábilem, acceptabilémque fácere dignéris:', 'ben + dita, apro + vada, rati + ficada, razoável e aceitável:');
  T('quamOblationem3', 'ut nobis Cor + pus, et San + guis fiat dilectíssimi Fílii tui, Dómini nostri Jesu Christi.', 'para que se torne para nós o Cor + po e o San + gue do vosso diletíssimo Filho, Nosso Senhor Jesus Cristo.');
  T('quiPridie1', 'Qui prídie quam paterétur,', 'O qual, na véspera da sua Paixão,');
  T('quiPridie2', 'accépit panem in sanctas ac venerábiles manus suas,', 'tomou o pão em suas santas e veneráveis mãos,');
  T('quiPridie3', 'et elevátis óculis in cælum ad te Deum, Patrem suum omnipoténtem,', 'e, elevando os olhos ao céu, a Vós, Deus, seu Pai todo-poderoso,');
  T('quiPridie4', 'tibi grátias agens,', 'dando-Vos graças,');
  T('quiPridie5', 'bene + díxit, fregit, dedítque discípulis suis, dicens: Accípite, et manducáte ex hoc omnes.', 'o aben + çoou, partiu e deu aos seus discípulos, dizendo: Tomai e comei dele todos.');
  T('hocEst', 'HOC EST ENIM CORPUS MEUM.', 'POIS ISTO É O MEU CORPO.');
  T('simili1', 'Símili modo postquam cenátum est,', 'Do mesmo modo, depois de cear,');
  T('simili2', 'accípiens et hunc præclárum Cálicem in sanctas ac venerábiles manus suas:', 'tomando também este precioso Cálice em suas santas e veneráveis mãos,');
  T('simili3', 'item tibi grátias agens,', 'dando-Vos graças novamente,');
  T('simili4', 'bene + díxit, dedítque discípulis suis, dicens: Accípite, et bíbite ex eo omnes.', 'o aben + çoou e deu aos seus discípulos, dizendo: Tomai e bebei dele todos.');
  T('hicEst', 'HIC EST ENIM CALIX SÁNGUINIS MEI, NOVI ET ÆTÉRNI TESTAMÉNTI: MYSTÉRIUM FÍDEI: QUI PRO VOBIS ET PRO MULTIS EFFUNDÉTUR IN REMISSIÓNEM PECCATÓRUM.', 'POIS ESTE É O CÁLICE DO MEU SANGUE, DO NOVO E ETERNO TESTAMENTO: MISTÉRIO DA FÉ: QUE SERÁ DERRAMADO POR VÓS E POR MUITOS PARA A REMISSÃO DOS PECADOS.');
  T('haecQuotiescumque', 'Hæc quotiescúmque fecéritis, in mei memóriam faciétis.', 'Todas as vezes que fizerdes isto, fazei-o em memória de mim.');
  T('undeEtMemores1', 'Unde et mémores, Dómine, nos servi tui, sed et plebs tua sancta, ejúsdem Christi Fílii tui, Dómini nostri, tam beátæ passiónis, nec non et ab ínferis resurrectiónis, sed et in cælos gloriósæ ascensiónis: offérimus præcláræ majestáti tuæ de tuis donis ac datis,', 'Por isso, Senhor, nós, vossos servos, e também o vosso povo santo, lembrando-nos da tão bem-aventurada Paixão do mesmo Cristo, vosso Filho, Nosso Senhor, bem como de sua Ressurreição dos infernos e de sua gloriosa Ascensão aos céus, oferecemos à vossa preclara majestade, de vossos próprios dons e dádivas,');
  T('undeEtMemores2', 'Hóstiam + puram, Hóstiam + sanctam, Hóstiam + immaculátam, Panem + sanctum vitæ ætérnæ, et Cálicem + salútis perpétuæ.', 'a Hóstia + pura, a Hóstia + santa, a Hóstia + imaculada, o Pão + santo da vida eterna e o Cálice + da salvação perpétua.');
  T('supraQuae', 'Supra quæ propítio ac seréno vultu respícere dignéris: et accépta habére, sicúti accépta habére dignátus es múnera púeri tui justi Abel, et sacrifícium Patriárchæ nostri Abrahæ: et quod tibi óbtulit summus sacérdos tuus Melchísedech, sanctum sacrifícium, immaculátam hóstiam.', 'Sobre estas oferendas dignai-Vos olhar com rosto propício e sereno, e aceitá-las, como Vos dignastes aceitar os dons do vosso servo, o justo Abel, o sacrifício do nosso Patriarca Abraão e o que Vos ofereceu o vosso sumo sacerdote Melquisedeque, sacrifício santo, hóstia imaculada.');
  T('supplices1', 'Súpplices te rogámus, omnípotens Deus: jube hæc perférri per manus sancti Angeli tui in sublíme altáre tuum, in conspéctu divínæ majestátis tuæ: ut, quotquot', 'Suplicantes Vos rogamos, ó Deus todo-poderoso: mandai que estas oferendas sejam levadas pelas mãos do vosso santo Anjo ao vosso altar sublime, à presença da vossa divina majestade, para que todos nós que,');
  T('supplices2', 'ex hac altáris participatióne sacrosánctum Fílii tui Cor + pus, et Sán + guinem sumpsérimus,', 'por esta participação do altar, recebermos o sacrossanto Cor + po e San + gue do vosso Filho,');
  T('supplices3', 'omni benedictióne cælésti et grátia repleámur. Per eúndem Christum, Dóminum nostrum. Amen.', 'sejamos repletos de toda bênção celeste e de toda graça. Pelo mesmo Cristo, Nosso Senhor. Amém.');
  T('mementoEtiam1', 'Meménto étiam, Dómine, famulórum famularúmque tuárum N. et N., qui nos præcessérunt cum signo fídei, et dórmiunt in somno pacis.', 'Lembrai-Vos também, Senhor, dos vossos servos e servas N. e N., que nos precederam com o sinal da fé e dormem o sono da paz.');
  T('mementoEtiam2', 'Ipsis, Dómine, et ómnibus in Christo quiescéntibus locum refrigérii, lucis, et pacis, ut indúlgeas, deprecámur. Per eúndem Christum, Dóminum nostrum. Amen.', 'A eles, Senhor, e a todos os que descansam em Cristo, Vos suplicamos que concedais o lugar do refrigério, da luz e da paz. Pelo mesmo Cristo, Nosso Senhor. Amém.');
  T('nobisQuoque1', 'Nobis quoque peccatóribus', 'Também a nós, pecadores,');
  T('nobisQuoque2', 'fámulis tuis, de multitúdine miseratiónum tuárum sperántibus, partem áliquam et societátem donáre dignéris, cum tuis sanctis Apóstolis et Martýribus: cum Joánne, Stéphano, Matthía, Bárnaba, Ignátio, Alexándro, Marcellíno, Petro, Felicitáte, Perpétua, Agatha, Lúcia, Agnéte, Cæcília, Anastásia, et ómnibus Sanctis tuis: intra quorum nos consórtium, non æstimátor mériti, sed véniæ, quǽsumus, largítor admítte. Per Christum, Dóminum nostrum.', 'vossos servos, que esperamos na multidão das vossas misericórdias, dignai-Vos conceder alguma parte e sociedade com os vossos santos Apóstolos e Mártires: com João, Estêvão, Matias, Barnabé, Inácio, Alexandre, Marcelino, Pedro, Felicidade, Perpétua, Águeda, Luzia, Inês, Cecília, Anastácia e com todos os vossos Santos; em cuja companhia Vos pedimos que nos admitais, não como juiz do mérito, mas como dispensador do perdão. Por Cristo, Nosso Senhor.');
  T('perQuem', 'Per quem hæc ómnia, Dómine, semper bona creas, sanctí + ficas, viví + ficas, bene + dícis et præstas nobis.', 'Por quem, Senhor, sempre criais todos estes bens, os santi + ficais, vivi + ficais, aben + çoais e no-los concedeis.');
  T('perIpsum1', 'Per Ip + sum, et cum Ip + so, et in Ip + so, est tibi Deo Patri + omnipoténti, in unitáte Spíritus + Sancti,', 'Por + Ele, e com + Ele, e n’+Ele, a Vós, Deus Pai + todo-poderoso, na unidade do Espírito + Santo,');
  T('perIpsum2', 'omnis honor, et glória.', 'toda a honra e glória.');

  // ---------------- Comunhão ----------------
  T('praeceptis', 'Orémus: Præcéptis salutáribus móniti, et divína institutióne formáti audémus dícere:', 'Oremos. Advertidos por salutares preceitos e formados pela instrução divina, ousamos dizer:');
  T('paterNoster', 'Pater noster, qui es in cælis. Sanctificétur nomen tuum. Advéniat regnum tuum. Fiat volúntas tua, sicut in cælo et in terra. Panem nostrum quotidiánum da nobis hódie. Et dimítte nobis débita nostra, sicut et nos dimíttimus debitóribus nostris. Et ne nos indúcas in tentatiónem:', 'Pai nosso, que estais nos céus, santificado seja o vosso nome; venha a nós o vosso reino; seja feita a vossa vontade, assim na terra como no céu. O pão nosso de cada dia nos dai hoje; perdoai-nos as nossas dívidas, assim como nós perdoamos aos nossos devedores; e não nos deixeis cair em tentação:');
  T('sedLibera', 'Sed líbera nos a malo.', 'Mas livrai-nos do mal.');
  T('liberaNos1', 'Líbera nos, quǽsumus, Dómine, ab ómnibus malis, prætéritis, præséntibus et futúris: et intercedénte beáta et gloriósa semper Vírgine Dei Genetríce María, cum beátis Apóstolis tuis Petro et Paulo, atque Andréa, et ómnibus Sanctis,', 'Livrai-nos, Senhor, Vos pedimos, de todos os males passados, presentes e futuros; e, pela intercessão da bem-aventurada e gloriosa sempre Virgem Maria, Mãe de Deus, com os vossos bem-aventurados Apóstolos Pedro e Paulo, e André, e todos os Santos,');
  T('liberaNos2', 'da propítius pacem in diébus nostris:', 'dai-nos propício a paz em nossos dias,');
  T('liberaNos3', 'ut, ope misericórdiæ tuæ adjúti, et a peccáto simus semper líberi et ab omni perturbatióne secúri.', 'para que, ajudados pelo auxílio da vossa misericórdia, sejamos sempre livres do pecado e seguros de toda perturbação.');
  T('perEundem1', 'Per eúndem Dóminum nostrum Jesum Christum, Fílium tuum.', 'Pelo mesmo Nosso Senhor Jesus Cristo, vosso Filho,');
  T('perEundem2', 'Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus.', 'que convosco vive e reina na unidade do Espírito Santo, Deus,');
  T('paxDomini', 'Pax + Dómini sit + semper + vobíscum.', 'A paz + do Senhor esteja + sempre + convosco.');
  T('haecCommixtio', 'Hæc commíxtio, et consecrátio Córporis et Sánguinis Dómini nostri Jesu Christi, fiat accipiéntibus nobis in vitam ætérnam. Amen.', 'Esta mistura e consagração do Corpo e do Sangue de Nosso Senhor Jesus Cristo seja para nós, que a recebemos, para a vida eterna. Amém.');
  T('agnus1', 'Agnus Dei, qui tollis peccáta mundi: miserére nobis.', 'Cordeiro de Deus, que tirais os pecados do mundo, tende piedade de nós.');
  T('agnus3', 'Agnus Dei, qui tollis peccáta mundi: dona nobis pacem.', 'Cordeiro de Deus, que tirais os pecados do mundo, dai-nos a paz.');
  T('agnusDef1', 'Agnus Dei, qui tollis peccáta mundi: dona eis réquiem.', 'Cordeiro de Deus, que tirais os pecados do mundo, dai-lhes o descanso.');
  T('agnusDef3', 'Agnus Dei, qui tollis peccáta mundi: dona eis réquiem sempitérnam.', 'Cordeiro de Deus, que tirais os pecados do mundo, dai-lhes o descanso eterno.');
  T('quiDixisti', 'Dómine Jesu Christe, qui dixísti Apóstolis tuis: Pacem relínquo vobis, pacem meam do vobis: ne respícias peccáta mea, sed fidem Ecclésiæ tuæ; eámque secúndum voluntátem tuam pacificáre et coadunáre dignéris: Qui vivis et regnas Deus per ómnia sǽcula sæculórum. Amen.', 'Senhor Jesus Cristo, que dissestes aos vossos Apóstolos: “Deixo-vos a paz, dou-vos a minha paz”, não olheis para os meus pecados, mas para a fé da vossa Igreja; e dignai-Vos pacificá-la e uni-la segundo a vossa vontade. Vós que viveis e reinais, Deus, por todos os séculos dos séculos. Amém.');
  T('filiDeiVivi', 'Dómine Jesu Christe, Fili Dei vivi, qui ex voluntáte Patris, cooperánte Spíritu Sancto, per mortem tuam mundum vivificásti: líbera me per hoc sacrosánctum Corpus et Sánguinem tuum ab ómnibus iniquitátibus meis, et univérsis malis: et fac me tuis semper inhærére mandátis, et a te numquam separári permíttas: Qui cum eódem Deo Patre et Spíritu Sancto vivis et regnas Deus in sǽcula sæculórum. Amen.', 'Senhor Jesus Cristo, Filho de Deus vivo, que, por vontade do Pai e com a cooperação do Espírito Santo, destes pela vossa morte a vida ao mundo, livrai-me, por este vosso sacrossanto Corpo e Sangue, de todas as minhas iniquidades e de todos os males; fazei que eu sempre adira aos vossos mandamentos e não permitais que jamais me separe de Vós. Vós que, com o mesmo Deus Pai e o Espírito Santo, viveis e reinais, Deus, pelos séculos dos séculos. Amém.');
  T('perceptio', 'Percéptio Córporis tui, Dómine Jesu Christe, quod ego indígnus súmere præsúmo, non mihi provéniat in judícium et condemnatiónem: sed pro tua pietáte prosit mihi ad tutaméntum mentis et córporis, et ad medélam percipiéndam: Qui vivis et regnas cum Deo Patre in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum. Amen.', 'A recepção do vosso Corpo, Senhor Jesus Cristo, que eu, indigno, ouso tomar, não se me converta em juízo e condenação; mas, por vossa bondade, me aproveite para defesa da alma e do corpo e como remédio salutar. Vós que viveis e reinais com Deus Pai na unidade do Espírito Santo, Deus, por todos os séculos dos séculos. Amém.');
  T('panemCaelestem', 'Panem cæléstem accípiam, et nomen Dómini invocábo.', 'Tomarei o Pão celeste e invocarei o nome do Senhor.');
  T('domineNonSum', 'Dómine, non sum dignus, ut intres sub tectum meum: sed tantum dic verbo, et sanábitur ánima mea.', 'Senhor, eu não sou digno de que entreis sob o meu teto; mas dizei uma só palavra e a minha alma será salva.');
  T('corpusDominiMeam', 'Corpus Dómini nostri Jesu Christi custódiat ánimam meam in vitam ætérnam. Amen.', 'O Corpo de Nosso Senhor Jesus Cristo guarde a minha alma para a vida eterna. Amém.');
  T('quidRetribuam', 'Quid retríbuam Dómino pro ómnibus, quæ retríbuit mihi? Cálicem salutáris accípiam, et nomen Dómini invocábo. Laudans invocábo Dóminum, et ab inimícis meis salvus ero.', 'Que retribuirei ao Senhor por todos os benefícios que me concedeu? Tomarei o cálice da salvação e invocarei o nome do Senhor. Invocarei o Senhor, louvando-O, e serei salvo dos meus inimigos.');
  T('sanguisDomini', 'Sanguis Dómini nostri Jesu Christi custódiat ánimam meam in vitam ætérnam. Amen.', 'O Sangue de Nosso Senhor Jesus Cristo guarde a minha alma para a vida eterna. Amém.');
  T('misereaturVestriComm', 'Misereátur vestri omnípotens Deus, et, dimíssis peccátis vestris, perdúcat vos ad vitam ætérnam.', 'Deus todo-poderoso tenha misericórdia de vós, perdoe os vossos pecados e vos conduza à vida eterna.');
  T('indulgentiamComm', 'Indulgéntiam, + absolutiónem et remissiónem peccatórum vestrórum tríbuat vobis omnípotens et miséricors Dóminus.', 'O Senhor todo-poderoso e misericordioso vos conceda o perdão, + a absolvição e a remissão dos vossos pecados.');
  T('confiteorComm', 'Confíteor Deo omnipoténti, beátæ Maríæ semper Vírgini, beáto Michaéli Archángelo, beáto Joánni Baptístæ, sanctis Apóstolis Petro et Paulo, ómnibus Sanctis, et tibi, pater: quia peccávi nimis cogitatióne, verbo et ópere: mea culpa, mea culpa, mea máxima culpa. Ideo precor beátam Maríam semper Vírginem, beátum Michaélem Archángelum, beátum Joánnem Baptístam, sanctos Apóstolos Petrum et Paulum, omnes Sanctos, et te, pater, oráre pro me ad Dóminum, Deum nostrum.', 'Eu pecador me confesso a Deus todo-poderoso… (o Confíteor dito pelo acólito em nome dos comungantes, segundo o costume anterior a 1960).');
  T('ecceAgnus', 'Ecce Agnus Dei, ecce qui tollit peccáta mundi.', 'Eis o Cordeiro de Deus, eis Aquele que tira os pecados do mundo.');
  T('corpusDominiTuam', 'Corpus Dómini nostri Jesu Christi custódiat ánimam tuam in vitam ætérnam. Amen.', 'O Corpo de Nosso Senhor Jesus Cristo guarde a tua alma para a vida eterna. Amém.');
  T('quodOre', 'Quod ore súmpsimus, Dómine, pura mente capiámus: et de múnere temporáli fiat nobis remédium sempitérnum.', 'O que recebemos com a boca, Senhor, acolhamo-lo com alma pura; e de dom temporal se nos torne remédio eterno.');
  T('corpusTuum', 'Corpus tuum, Dómine, quod sumpsi, et Sanguis, quem potávi, adhǽreat viscéribus meis: et præsta; ut in me non remáneat scélerum mácula, quem pura et sancta refecérunt sacraménta: Qui vivis et regnas in sǽcula sæculórum. Amen.', 'O vosso Corpo, Senhor, que recebi, e o Sangue que bebi, se unam às minhas entranhas; e concedei que não fique em mim mancha alguma de pecado, a mim, a quem restauraram estes puros e santos sacramentos. Vós que viveis e reinais pelos séculos dos séculos. Amém.');

  // ---------------- Conclusão ----------------
  T('iteMissaEst', 'Ite, missa est.', 'Ide, a Missa está terminada.');
  T('iteMissaEstAll', 'Ite, missa est, allelúja, allelúja.', 'Ide, a Missa está terminada, aleluia, aleluia.');
  T('deoGratiasAll', 'Deo grátias, allelúja, allelúja.', 'Graças a Deus, aleluia, aleluia.');
  T('benedicamus', 'Benedicámus Dómino.', 'Bendigamos ao Senhor.');
  T('requiescant', 'Requiéscant in pace.', 'Descansem em paz.');
  T('humiliate', 'Humiliáte cápita vestra Deo.', 'Inclinai as vossas cabeças diante de Deus.');
  T('placeat', 'Pláceat tibi, sancta Trínitas, obséquium servitútis meæ: et præsta; ut sacrifícium, quod óculis tuæ majestátis indígnus óbtuli, tibi sit acceptábile, mihíque et ómnibus, pro quibus illud óbtuli, sit, te miseránte, propitiábile. Per Christum, Dóminum nostrum. Amen.', 'Seja-Vos agradável, ó Santíssima Trindade, a homenagem da minha servidão; e concedei que o sacrifício que eu, indigno, ofereci aos olhos da vossa majestade, Vos seja aceitável e, pela vossa misericórdia, seja propiciatório para mim e para todos aqueles por quem o ofereci. Por Cristo, Nosso Senhor. Amém.');
  T('benedicat1', 'Benedícat vos omnípotens Deus,', 'Abençoe-vos Deus todo-poderoso,');
  T('benedicat2', 'Pater, et Fílius, + et Spíritus Sanctus.', 'Pai, e Filho, + e Espírito Santo.');
  T('initiumJoannem', 'Inítium + sancti Evangélii secúndum Joánnem.', 'Início + do santo Evangelho segundo São João.');
  T('inPrincipio1', 'In princípio erat Verbum, et Verbum erat apud Deum, et Deus erat Verbum. Hoc erat in princípio apud Deum. Omnia per ipsum facta sunt: et sine ipso factum est nihil, quod factum est: in ipso vita erat, et vita erat lux hóminum: et lux in ténebris lucet, et ténebræ eam non comprehendérunt. Fuit homo missus a Deo, cui nomen erat Joánnes. Hic venit in testimónium, ut testimónium perhibéret de lúmine, ut omnes créderent per illum. Non erat ille lux, sed ut testimónium perhibéret de lúmine. Erat lux vera, quæ illúminat omnem hóminem veniéntem in hunc mundum. In mundo erat, et mundus per ipsum factus est, et mundus eum non cognóvit. In própria venit, et sui eum non recepérunt. Quotquot autem recepérunt eum, dedit eis potestátem fílios Dei fíeri, his, qui credunt in nómine ejus: qui non ex sanguínibus, neque ex voluntáte carnis, neque ex voluntáte viri, sed ex Deo nati sunt.', 'No princípio era o Verbo, e o Verbo estava junto de Deus, e o Verbo era Deus. Ele estava no princípio junto de Deus. Todas as coisas foram feitas por Ele, e sem Ele nada foi feito do que foi feito. N’Ele estava a vida, e a vida era a luz dos homens; e a luz resplandece nas trevas, e as trevas não a compreenderam. Houve um homem enviado por Deus, cujo nome era João. Este veio como testemunha, para dar testemunho da luz, a fim de que todos cressem por meio dele. Ele não era a luz, mas veio para dar testemunho da luz. Era a luz verdadeira, que ilumina todo homem que vem a este mundo. Estava no mundo, e o mundo foi feito por Ele, e o mundo não O conheceu. Veio para o que era seu, e os seus não O receberam. Mas a todos os que O receberam deu o poder de se tornarem filhos de Deus: aos que creem no seu nome, os quais não nasceram do sangue, nem da vontade da carne, nem da vontade do homem, mas de Deus.');
  T('inPrincipio2', 'Et Verbum caro factum est,', 'E o Verbo se fez carne,');
  T('inPrincipio3', 'et habitávit in nobis: et vídimus glóriam ejus, glóriam quasi Unigéniti a Patre, plenum grátiæ et veritátis.', 'e habitou entre nós; e vimos a sua glória, glória como do Unigênito do Pai, cheio de graça e de verdade.');

  // ---------------- Orações leoninas (após a Missa rezada) ----------------
  T('aveMaria1', 'Ave María, grátia plena, Dóminus tecum, benedícta tu in muliéribus, et benedíctus fructus ventris tui, Jesus.', 'Ave Maria, cheia de graça, o Senhor é convosco; bendita sois vós entre as mulheres, e bendito é o fruto do vosso ventre, Jesus.');
  T('aveMaria2', 'Sancta María, Mater Dei, ora pro nobis peccatóribus, nunc et in hora mortis nostræ. Amen.', 'Santa Maria, Mãe de Deus, rogai por nós, pecadores, agora e na hora da nossa morte. Amém.');
  T('salveRegina', 'Salve Regína, Mater misericórdiæ, vita, dulcédo, et spes nostra, salve. Ad te clamámus, éxsules fílii Evæ. Ad te suspirámus, geméntes et flentes in hac lacrimárum valle. Eja ergo, advocáta nostra, illos tuos misericórdes óculos ad nos convérte. Et Jesum, benedíctum fructum ventris tui, nobis post hoc exsílium osténde. O clemens, o pia, o dulcis Virgo María.', 'Salve, Rainha, Mãe de misericórdia, vida, doçura e esperança nossa, salve! A vós bradamos, os degredados filhos de Eva. A vós suspiramos, gemendo e chorando neste vale de lágrimas. Eia, pois, advogada nossa, esses vossos olhos misericordiosos a nós volvei. E, depois deste desterro, mostrai-nos Jesus, bendito fruto do vosso ventre. Ó clemente, ó piedosa, ó doce Virgem Maria.');
  T('oraProNobis', 'Ora pro nobis, sancta Dei Génetrix.', 'Rogai por nós, santa Mãe de Deus.');
  T('utDigni', 'Ut digni efficiámur promissiónibus Christi.', 'Para que sejamos dignos das promessas de Cristo.');
  T('deusRefugium', 'Orémus. Deus, refúgium nostrum et virtus, pópulum ad te clamántem propítius réspice; et intercedénte gloriósa et immaculáta Vírgine Dei Genetríce María, cum beáto Joseph, ejus Sponso, ac beátis Apóstolis tuis Petro et Paulo, et ómnibus Sanctis, quas pro conversióne peccatórum, pro libertáte et exaltatióne sanctæ Matris Ecclésiæ, preces effúndimus, miséricors et benígnus exáudi. Per eúndem Christum, Dóminum nostrum. Amen.', 'Oremos. Ó Deus, nosso refúgio e fortaleza, olhai propício para o povo que clama a Vós; e, pela intercessão da gloriosa e imaculada Virgem Maria, Mãe de Deus, de São José, seu Esposo, dos vossos bem-aventurados Apóstolos Pedro e Paulo e de todos os Santos, ouvi, misericordioso e benigno, as preces que Vos dirigimos pela conversão dos pecadores, pela liberdade e exaltação da santa Mãe Igreja. Pelo mesmo Cristo, Nosso Senhor. Amém.');
  T('sancteMichael', 'Sancte Míchaël Archángele, defénde nos in prǽlio; contra nequítiam et insídias diáboli esto præsídium. Imperet illi Deus, súpplices deprecámur: tuque, Princeps milítiæ cæléstis, sátanam aliósque spíritus malígnos, qui ad perditiónem animárum pervagántur in mundo, divína virtúte in inférnum detrúde. Amen.', 'São Miguel Arcanjo, defendei-nos no combate; sede o nosso amparo contra a maldade e as ciladas do demônio. Ordene-lhe Deus, instantemente o pedimos; e vós, Príncipe da milícia celeste, pela virtude divina, precipitai no inferno a Satanás e aos outros espíritos malignos, que andam pelo mundo para perder as almas. Amém.');
  T('corJesu', 'Cor Jesu sacratíssimum.', 'Sacratíssimo Coração de Jesus.');
  T('miserereNobis', 'Miserére nobis.', 'Tende piedade de nós.');

  // ---------------- Prefácios (português) ----------------
  // O latim vem do Divinum Officium (DG.data.propersRaw.prefaces); aqui, a tradução.
  const PRE = 'Verdadeiramente é digno e justo, razoável e salutar, que sempre e em toda parte Vos demos graças, Senhor santo, Pai todo-poderoso, Deus eterno';
  const ANG = 'E por isso, com os Anjos e Arcanjos, com os Tronos e Dominações, e com toda a milícia do exército celeste, cantamos o hino da vossa glória, dizendo sem cessar:';
  const PERQUEM = 'Por quem os Anjos louvam a vossa majestade, as Dominações a adoram, as Potestades a temem. Os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram com unânime exultação. Com eles, Vos pedimos, permiti que se unam também as nossas vozes, dizendo em humilde louvor:';
  O.prefacesPt = {
    Communis: PRE + ', por Cristo, Nosso Senhor. ' + PERQUEM,
    Trinitate: PRE + '. Que, com o vosso Filho unigênito e o Espírito Santo, sois um só Deus, um só Senhor, não na singularidade de uma só pessoa, mas na Trindade de uma só substância. Pois o que, por vossa revelação, cremos da vossa glória, isso mesmo cremos, sem diferença nem distinção, do vosso Filho e do Espírito Santo. De modo que, na confissão da verdadeira e eterna Divindade, adoremos a propriedade nas pessoas, a unidade na essência e a igualdade na majestade. A qual louvam os Anjos e os Arcanjos, os Querubins e os Serafins, que não cessam de clamar todos os dias, dizendo a uma só voz:',
    Nat: PRE + '. Porque, pelo mistério do Verbo encarnado, brilhou aos olhos da nossa alma uma nova luz da vossa claridade, para que, conhecendo a Deus visivelmente, por Ele sejamos arrebatados ao amor das coisas invisíveis. ' + ANG,
    Epi: PRE + '. Porque, aparecendo o vosso Unigênito na substância da nossa mortalidade, nos restaurou com a nova luz da sua imortalidade. ' + ANG,
    Quad: PRE + '. Que, pelo jejum corporal, reprimis os vícios, elevais a alma, concedeis a virtude e o prêmio, por Cristo, Nosso Senhor. ' + PERQUEM,
    Quad5: PRE + '. Que estabelecestes a salvação do gênero humano no lenho da Cruz, para que, donde nascera a morte, dali ressurgisse a vida, e aquele que vencera no lenho, no lenho também fosse vencido, por Cristo, Nosso Senhor. ' + PERQUEM,
    Pasch: 'Verdadeiramente é digno e justo, razoável e salutar, glorificar-Vos, Senhor, em todo tempo, mas sobretudo {DIE} mais gloriosamente, quando Cristo, nossa Páscoa, foi imolado. Pois Ele é o verdadeiro Cordeiro, que tirou os pecados do mundo; que, morrendo, destruiu a nossa morte e, ressuscitando, restaurou a vida. ' + ANG,
    Asc: PRE + ', por Cristo, Nosso Senhor. O qual, depois da sua Ressurreição, apareceu manifestamente a todos os seus discípulos e, à vista deles, foi elevado ao céu, para nos fazer participantes da sua divindade. ' + ANG,
    Spiritu: PRE + ', por Cristo, Nosso Senhor. O qual, subindo acima de todos os céus e sentando-Se à vossa direita, derramou {HOD}sobre os filhos de adoção o Espírito Santo prometido. Por isso, com transbordante alegria, exulta o mundo inteiro por toda a terra. E também as Virtudes celestes e as Potestades angélicas cantam o hino da vossa glória, dizendo sem cessar:',
    Maria: PRE + '. E de Vos louvar, bendizer e glorificar na {INS} da bem-aventurada sempre Virgem Maria. A qual, pela sombra do Espírito Santo, concebeu o vosso Unigênito e, permanecendo a glória da virgindade, deu ao mundo a luz eterna, Jesus Cristo, Nosso Senhor. ' + PERQUEM,
    Joseph: PRE + '. E de Vos glorificar com os devidos louvores, bendizer e exaltar na {INS} de São José; o qual, como varão justo, foi por Vós dado por esposo à Virgem Mãe de Deus e, como servo fiel e prudente, foi constituído sobre a vossa família, para que, com paternal solicitude, guardasse o vosso Unigênito, concebido pela sombra do Espírito Santo, Jesus Cristo, Nosso Senhor. ' + PERQUEM,
    Apostolis: 'Verdadeiramente é digno e justo, razoável e salutar, suplicar-Vos humildemente, Senhor, que não abandoneis, Pastor eterno, o vosso rebanho, mas, pelos vossos bem-aventurados Apóstolos, o guardeis com contínua proteção; para que seja governado pelos mesmos chefes que, como vigários da vossa obra, lhe destes por pastores. ' + ANG,
    Regis: PRE + '. Que, com o óleo da exultação, ungistes Sacerdote eterno e Rei do universo o vosso Filho unigênito, Nosso Senhor Jesus Cristo, para que, oferecendo-Se a Si mesmo no altar da Cruz como hóstia imaculada e pacífica, consumasse os mistérios da redenção humana; e, submetidas ao seu império todas as criaturas, entregasse à vossa imensa Majestade um reino eterno e universal: reino de verdade e de vida, reino de santidade e de graça, reino de justiça, de amor e de paz. ' + ANG,
    Cord: PRE + '. Que quisestes que o vosso Filho unigênito, pendente da Cruz, fosse traspassado pela lança do soldado, para que o Coração aberto, santuário da divina liberalidade, derramasse sobre nós torrentes de misericórdia e de graça; e, nunca deixando de arder de amor por nós, fosse para as almas piedosas lugar de repouso e para os penitentes refúgio aberto de salvação. ' + ANG,
    Defunctorum: PRE + ', por Cristo, Nosso Senhor. Em quem brilhou para nós a esperança da feliz ressurreição, para que aqueles a quem entristece a certeza da morte, os console a promessa da futura imortalidade. Pois aos vossos fiéis, Senhor, a vida não é tirada, mas transformada; e, desfeita a morada deste exílio terreno, adquire-se no céu uma habitação eterna. ' + ANG,
  };
  O.prefaceNames = {
    Communis: 'Prefácio comum', Trinitate: 'Prefácio da Santíssima Trindade', Nat: 'Prefácio do Natal', Epi: 'Prefácio da Epifania', Quad: 'Prefácio da Quaresma', Quad5: 'Prefácio da Santa Cruz', Pasch: 'Prefácio Pascal', Asc: 'Prefácio da Ascensão', Spiritu: 'Prefácio do Espírito Santo', Maria: 'Prefácio de Nossa Senhora', Joseph: 'Prefácio de São José', Apostolis: 'Prefácio dos Apóstolos', Regis: 'Prefácio de Cristo Rei', Cord: 'Prefácio do Sagrado Coração', Defunctorum: 'Prefácio dos Defuntos',
  };

  DG.data.ordo = O;
})(window.DG = window.DG || {});
